def _best_period(coords, n):
    best = (0, 0, [])
    for step in range(2, n + 1):
        groups = {}
        for x in coords:
            groups.setdefault(x % step, []).append(x)
        for xs in groups.values():
            if len(xs) >= 2:
                # Keep the longest evenly spaced progression, maximizing its span as a tie-break.
                if (len(xs), step) > (best[0], best[1]):
                    best = (len(xs), step, xs)
    return best

def transform(grid):
    h, w = len(grid), len(grid[0])
    rm = [_mode(row) for row in grid]
    cm = [_mode([grid[r][c] for r in range(h)]) for c in range(w)]
    colors = set(v for v, f in rm if f >= .62) & set(v for v, f in cm if f >= .62)
    choices = []
